using System.Collections.Concurrent;
using UpdateDeck.Core;
using Xunit;
namespace UpdateDeck.Tests;

public sealed class ImmediateProgress<T>(Action<T> action) : IProgress<T>{public void Report(T value)=>action(value);}
public sealed class SimulatedExecutor : IUpdateExecutor
{
    public readonly ConcurrentDictionary<string,int> Calls=new();
    public readonly Dictionary<string,Queue<ExecutionResult>> Outcomes=[];
    public OperationState Verification=OperationState.Verified;
    public int VerifyCount;
    public Func<Software,Task>? BeforeExecute;
    public async Task<ExecutionResult> ExecuteAsync(Software app,IProgress<string> progress,CancellationToken cancellation){Calls.AddOrUpdate(app.Id,1,(_,n)=>n+1);if(BeforeExecute!=null)await BeforeExecute(app);return Outcomes.TryGetValue(app.Id,out var results)&&results.Count>0?results.Dequeue():new(OperationState.AwaitingVerification,"fixture completed");}
    public Task<ExecutionResult> VerifyAsync(Software app,CancellationToken cancellation){VerifyCount++;return Task.FromResult(new ExecutionResult(Verification,"fixture verification"));}
}
public sealed class SimulatedVendor : IVendorLauncher{public int Count;public Task<ExecutionResult> LaunchAsync(string vendorId,CancellationToken cancellation){Count++;return Task.FromResult(new ExecutionResult(OperationState.Handoff,"fixture handoff"));}}
public class QueueTests
{
    [Fact]public async Task UnverifiedTargetAfterParentExitStopsPendingWorkAndRequiresInspection()
    {
        var executor=new SimulatedExecutor{Verification=OperationState.AwaitingVerification};var store=new StateStore(Fixture.Temp());
        var result=await new QueueEngine(executor,store,new SimulatedVendor()).RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);
        Assert.Equal(OperationState.AwaitingVerification,result[0].State);Assert.True(result[0].RequiresInspection);Assert.Equal(OperationState.Cancelled,result[1].State);Assert.False(executor.Calls.ContainsKey("two"));
        await Assert.ThrowsAsync<InvalidOperationException>(()=>new QueueEngine(executor,store,new SimulatedVendor()).RunAsync(Fixture.Plan(Fixture.App("three")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null));
    }
    [Fact]public async Task MonitorTimeoutAfterRetryStillStopsLaterWork(){var e=new SimulatedExecutor{Verification=OperationState.AwaitingVerification};e.Outcomes["one"]=new([new(OperationState.Failed,"transient download",Transient:true),new(OperationState.AwaitingVerification,"monitor limit",StopQueue:true)]);var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var result=await q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);Assert.Equal(2,e.Calls["one"]);Assert.True(result[0].RequiresInspection);Assert.Equal(OperationState.Cancelled,result[1].State);}
    [Fact]public async Task UnexpectedExecutionExceptionStopsPendingWorkAndRequiresInspection(){var e=new SimulatedExecutor{BeforeExecute=_=>throw new IOException("fixture monitoring failure")};var store=new StateStore(Fixture.Temp());var q=new QueueEngine(e,store,new SimulatedVendor());var result=await q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);Assert.True(result[0].RequiresInspection);Assert.Equal(OperationState.Cancelled,result[1].State);await Assert.ThrowsAsync<InvalidOperationException>(()=>q.RunAsync(Fixture.Plan(Fixture.App("three")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null));}
    [Fact]public async Task DuplicatePlanCannotRunAnInstallationTwice(){var e=new SimulatedExecutor();var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());await Assert.ThrowsAsync<InvalidOperationException>(()=>q.RunAsync(Fixture.Plan(Fixture.App(),Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null));Assert.Empty(e.Calls);}
    [Fact]public void EndedParentProcessIsObservedWithoutClearingPossibleChildInstallerHold(){var store=new StateStore(Fixture.Temp());store.SaveOperation(new(){Id="known",State=OperationState.AwaitingVerification,RequiresInspection=true,ActiveProcessId=44,ActiveProcessStartedUtcTicks=55});store.SaveOperation(new(){Id="unknown",State=OperationState.Interrupted,RequiresInspection=true});QueueEngine.ReconcileMonitors(store,_=>false);var known=store.LoadOperations().Single(x=>x.Id=="known");Assert.True(known.RequiresInspection);Assert.True(known.RecordedProcessEnded);Assert.True(store.LoadOperations().Single(x=>x.Id=="unknown").RequiresInspection);QueueEngine.ReconcileMonitors(store,_=>false);Assert.Equal(known.Message,store.LoadOperations().Single(x=>x.Id=="known").Message);Assert.All(store.LoadOperations(),x=>Assert.NotEqual(OperationState.Verified,x.State));}
    [Fact]public void UnreadableRecordedProcessDoesNotReleaseMonitoringHold(){var store=new StateStore(Fixture.Temp());store.SaveOperation(new(){State=OperationState.AwaitingVerification,RequiresInspection=true,ActiveProcessId=44,ActiveProcessStartedUtcTicks=55});QueueEngine.ReconcileMonitors(store,_=>null);Assert.True(Assert.Single(store.LoadOperations()).RequiresInspection);}
    [Fact]public async Task MixedOutcomesContinueAndNeverEquateExecutionWithVerification()
    {
        var executor=new SimulatedExecutor();executor.Outcomes["failure"]=new([new(OperationState.Failed,"installer failure")]);executor.Outcomes["interaction"]=new([new(OperationState.InteractionRequired,"license required")]);
        var store=new StateStore(Fixture.Temp());var vendor=new SimulatedVendor();var queue=new QueueEngine(executor,store,vendor);var handoff=Fixture.App("vendor") with{VendorId="native"};var plan=Fixture.Plan(Fixture.App("success"),Fixture.App("failure"),Fixture.App("interaction")) with{Handoffs=[new(handoff,"Handoff","")]};
        var result=await queue.RunAsync(plan,true,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);
        Assert.Equal(new[]{OperationState.Verified,OperationState.Failed,OperationState.InteractionRequired,OperationState.Handoff},result.Select(x=>x.State));Assert.Equal(1,executor.VerifyCount);Assert.Equal(1,vendor.Count);Assert.Equal(4,store.LoadOperations().Count);
    }
    [Fact]public async Task SuccessfulExitCanRemainUnverified(){var e=new SimulatedExecutor{Verification=OperationState.AwaitingVerification};var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());Assert.Equal(OperationState.AwaitingVerification,Assert.Single(await q.RunAsync(Fixture.Plan(Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null)).State);}
    [Fact]public async Task TransientFailureRetriesOnce(){var e=new SimulatedExecutor();e.Outcomes["one"]=new([new(OperationState.Failed,"network",Transient:true),new(OperationState.AwaitingVerification,"retry ok")]);var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var r=await q.RunAsync(Fixture.Plan(Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);Assert.Equal(2,e.Calls["one"]);Assert.Equal(OperationState.Verified,r[0].State);}
    [Fact]public async Task PauseAndCancelDuringRetryBackoffPreventAnotherInstallerAttempt()
    {
        var first=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var executor=new SimulatedExecutor{BeforeExecute=_=>{first.TrySetResult();return Task.CompletedTask;}};executor.Outcomes["one"]=new([new(OperationState.Failed,"network",Transient:true)]);
        var queue=new QueueEngine(executor,new StateStore(Fixture.Temp()),new SimulatedVendor(),TimeSpan.FromMilliseconds(80));var run=queue.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);
        await first.Task;queue.Pause();await Task.Delay(220);Assert.Equal(1,executor.Calls["one"]);Assert.False(run.IsCompleted);queue.CancelPending();var result=await run.WaitAsync(TimeSpan.FromSeconds(3));Assert.Equal(1,executor.Calls["one"]);Assert.All(result,x=>Assert.Equal(OperationState.Cancelled,x.State));Assert.False(executor.Calls.ContainsKey("two"));
    }
    [Fact]public async Task AChangedPreflightIsCheckedAgainBeforeRetry()
    {
        int checks=0;var executor=new SimulatedExecutor();executor.Outcomes["one"]=new([new(OperationState.Failed,"network",Transient:true)]);var queue=new QueueEngine(executor,new StateStore(Fixture.Temp()),new SimulatedVendor(),TimeSpan.Zero);
        var result=await queue.RunAsync(Fixture.Plan(Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>++checks==1?null:"Application started during retry backoff");Assert.Equal(1,executor.Calls["one"]);Assert.Equal(OperationState.Deferred,Assert.Single(result).State);Assert.Equal(2,checks);
    }
    [Fact]public async Task PermanentFailureNeverRetries(){var e=new SimulatedExecutor();e.Outcomes["one"]=new([new(OperationState.Failed,"integrity failure")]);var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());await q.RunAsync(Fixture.Plan(Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);Assert.Equal(1,e.Calls["one"]);}
    [Fact]public async Task PauseAndCancelOnlyAffectPendingWork()
    {
        var started=new TaskCompletionSource();var finish=new TaskCompletionSource();var e=new SimulatedExecutor{BeforeExecute=async _=>{started.TrySetResult();await finish.Task;}};
        var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var run=q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);
        await started.Task.WaitAsync(TimeSpan.FromSeconds(10));q.Pause();q.CancelPending();Assert.False(run.IsCompleted);finish.SetResult();var result=await run;Assert.Equal(OperationState.Verified,result[0].State);Assert.Equal(OperationState.Cancelled,result[1].State);Assert.False(e.Calls.ContainsKey("two"));
    }
    [Fact]public async Task RebootStopsSubsequentInstallers(){var e=new SimulatedExecutor();e.Outcomes["one"]=new([new(OperationState.AwaitingVerification,"reboot",3010,true)]);var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var result=await q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);Assert.True(result[0].RebootRequired);Assert.Equal(OperationState.Cancelled,result[1].State);}
    [Fact]public async Task ResumeContinuesOnlyAfterThePausedBoundary(){var started=new TaskCompletionSource();var finish=new TaskCompletionSource();var e=new SimulatedExecutor{BeforeExecute=async a=>{if(a.Id=="one"){started.SetResult();await finish.Task;}}};var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var run=q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);await started.Task;q.Pause();finish.SetResult();await Task.Delay(160);Assert.False(e.Calls.ContainsKey("two"));q.Resume();var result=await run.WaitAsync(TimeSpan.FromSeconds(5));Assert.All(result,x=>Assert.Equal(OperationState.Verified,x.State));}
    [Fact]public async Task SkipNeverStartsTheSelectedPendingInstaller(){var started=new TaskCompletionSource();var finish=new TaskCompletionSource();var e=new SimulatedExecutor{BeforeExecute=async _=>{started.TrySetResult();await finish.Task;}};var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var run=q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);await started.Task;q.Skip("two");finish.SetResult();var result=await run.WaitAsync(TimeSpan.FromSeconds(5));Assert.Equal(OperationState.Cancelled,result[1].State);Assert.False(e.Calls.ContainsKey("two"));}
    [Fact]public async Task UnknownActiveInstallerStopsLaterWork(){var e=new SimulatedExecutor{Verification=OperationState.AwaitingVerification};e.Outcomes["one"]=new([new(OperationState.AwaitingVerification,"monitor limit",StopQueue:true)]);var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var result=await q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);Assert.Equal(OperationState.AwaitingVerification,result[0].State);Assert.Equal(OperationState.Cancelled,result[1].State);Assert.False(e.Calls.ContainsKey("two"));}
    [Fact]public async Task RevalidatesEachItemAtSafeBoundary(){var e=new SimulatedExecutor();var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var result=await q.RunAsync(Fixture.Plan(Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>"Application started running");Assert.Equal(OperationState.Deferred,result[0].State);Assert.Empty(e.Calls);}
    [Fact]public async Task SavesWholePendingQueueBeforeSideEffects(){var store=new StateStore(Fixture.Temp());var e=new SimulatedExecutor{BeforeExecute=_=>{Assert.Equal(2,store.LoadOperations().Count);return Task.CompletedTask;}};var q=new QueueEngine(e,store,new SimulatedVendor());await q.RunAsync(Fixture.Plan(Fixture.App("one"),Fixture.App("two")),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);}
    [Fact]public async Task ConcurrentQueuesAreRejected(){var start=new TaskCompletionSource();var release=new TaskCompletionSource();var e=new SimulatedExecutor{BeforeExecute=async _=>{start.SetResult();await release.Task;}};var q=new QueueEngine(e,new StateStore(Fixture.Temp()),new SimulatedVendor());var run=q.RunAsync(Fixture.Plan(Fixture.App()),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null);await start.Task;await Assert.ThrowsAsync<InvalidOperationException>(()=>q.RunAsync(Fixture.Plan(),false,new ImmediateProgress<QueueProgress>(_=>{}),_=>null));release.SetResult();await run;}
}
